import { test, expect } from '@playwright/test';

test.describe('Product Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display search results when a valid keyword is entered', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('laptop');
    await page.getByRole('button', { name: /search/i }).click();

    const results = await page.getByText(/laptop/i);
    await expect(results).toBeVisible();
  });

  test('should display no results message for an invalid keyword', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('nonexistentproduct');
    await page.getByRole('button', { name: /search/i }).click();

    const noResultsMessage = await page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();
  });
});
